import statistics


def position(valeurs):
    return [round(statistics.mean(valeurs), 2), statistics.median(valeurs)]

def mediane(valeurs):
    if not valeurs:
        return None
    rangees = sorted(valeurs)
    milieu = len(rangees) // 2
    if len(rangees) % 2 == 1:
        return rangees[milieu]
    return (rangees[milieu - 1] + rangees[milieu]) / 2

